using System;using System.IO;using System.Collections;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {
 public sealed class GuidanceUITests {
  string dir;GameRuntime game;static void Click(string name){var b=GameObject.Find(name)?.GetComponent<Button>();Assert.That(b,Is.Not.Null,name);Assert.That(b.interactable,Is.True,name);b.onClick.Invoke();}
  [UnitySetUp]public IEnumerator Setup(){dir=Path.Combine(Path.GetTempPath(),"unity-goals-ui-"+Guid.NewGuid());Directory.CreateDirectory(dir);GameRuntime.SavePathOverride=Path.Combine(dir,"save.json");var store=new AtomicSaveStore(GameRuntime.SavePathOverride,new UnitySaveCodec());var s=store.Load(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()).State;s.Story=StoryState.Migrated();s.Retention.aiName="AURA";store.Save(s);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;Directory.Delete(dir,true);}
  [UnityTest]public IEnumerator RealPinNavigateReloadClearAndDiagnosticExport(){Click("ResearchTab");yield return null;Click("GoalsAccess");yield return null;var credits=game.State.Credits;Click("PinGoal-hardware-sbc");Assert.That(game.State.Guidance.hasPinned,Is.True);Assert.That(game.State.Guidance.pinned.id,Is.EqualTo("sbc"));Assert.That(game.State.Credits.CompareTo(credits),Is.Zero);Click("GoToCurrentGoal");yield return null;yield return null;Assert.That(GameObject.Find("hardware-sbc"),Is.Not.Null);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Guidance.pinned.id,Is.EqualTo("sbc"));Click("ResearchTab");yield return null;Click("GoalsAccess");yield return null;Click("ClearPinnedGoal");Assert.That(game.State.Guidance.hasPinned,Is.False);foreach(string language in SettingsCatalog.Languages){game.Act(s=>SettingsRules.Change(s,"language",language));game.Show("goals");yield return null;yield return null;foreach(int width in new[]{320,390,430})WorkshopTests.Capture(width,width==320?568:width==390?844:932,"/tmp/unity-goals-"+language+"-"+width+".png");}game.Show("storage");yield return null;Click("ExportLocalDiagnostics");string[] files=Directory.GetFiles(Path.Combine(dir,"Exports"),"diagnostics-*.json");Assert.That(files.Length,Is.EqualTo(1));string raw=File.ReadAllText(files[0]);Assert.That(raw,Does.Contain("file-runtime"));Assert.That(raw,Does.Contain("lastSuccessfulSave"));Assert.That(game.Diagnostics.hasSave,Is.True);Assert.That(game.Diagnostics.lastSaveBytes,Is.GreaterThan(0));Assert.That(game.Diagnostics.ticks,Is.GreaterThan(0));}
  [UnityTest]public IEnumerator DamagedMainHasReachableExplicitRecoveryAndKeepsOriginal(){game.Show("storage");yield return null;Click("ExportUnitySave");string source=Directory.GetFiles(Path.Combine(dir,"Exports"),"unity-*.json")[0];File.WriteAllText(game.SavePath,"damaged original from recovery UI test");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.Writable,Is.False);Click("ResearchTab");yield return null;Click("StorageAccess");yield return null;GameObject.Find("RecoveryPathInput").GetComponent<InputField>().text=source;Click("InspectRecoveryPath");Assert.That(game.Writable,Is.False,"Preview cannot overwrite the original");Click("ConfirmRecovery");yield return null;Assert.That(game.Writable,Is.True);Assert.That(Directory.GetFiles(dir,"*-original-*").Length,Is.GreaterThan(0));bool preserved=false;foreach(string file in Directory.GetFiles(dir,"*-original-*"))preserved|=File.ReadAllText(file)=="damaged original from recovery UI test";Assert.That(preserved,Is.True);Assert.That(game.Diagnostics.recoveries,Is.GreaterThan(0));}
 }
}
